// src/lib/mcp/tools/list-objectives.ts
import { defineTool as defineTool7 } from "npm:@lovable.dev/mcp-js@2.0.4";
import { z as z6 } from "npm:zod@^3.25.76";
var list_objectives_default = defineTool7({
  name: "list_objectives",
  title: "Listar objetivos (OKRs)",
  description: "Lista objetivos organizacionais e/ou de time da unidade, com ciclo, respons\xE1vel, sa\xFAde, progresso m\xE9dio e quantidade de KRs.",
  inputSchema: {
    bu: buArg,
    escopo: z6.enum(["org", "team", "todos"]).optional().describe("Padr\xE3o: todos."),
    ciclo: z6.string().optional().describe("Nome do ciclo (ex.: 2026-Q3). Omita para o ciclo ativo."),
    time: z6.string().optional().describe("Nome do time."),
    status: z6.enum(["draft", "active", "completed", "cancelled", "discarded"]).optional(),
    busca: searchArg,
    limite: limitArg
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ bu, escopo, ciclo, time, status, busca, limite }, ctx) => {
    const scope = await resolveScope(ctx, bu);
    const { supabase, buId } = scope;
    const limit = clampLimit(limite, 100);
    let cycleId = null;
    let cycleName = null;
    const { data: cycles, error: cyclesError } = await supabase.from("cycles").select("id, name, status").eq("bu_id", buId).order("start_date", { ascending: false }).limit(60);
    assertNoError(cyclesError, "ciclos");
    const chosenCycle = ciclo ? (cycles ?? []).find((c) => c.name.toLowerCase().includes(ciclo.toLowerCase())) : (cycles ?? []).find((c) => c.status === "active");
    if (chosenCycle) {
      cycleId = chosenCycle.id;
      cycleName = chosenCycle.name;
    }
    let teamId = null;
    if (time) {
      const { data: teams } = await supabase.from("teams").select("id, name").eq("bu_id", buId).is("deleted_at", null).ilike("name", `%${time}%`).limit(1);
      teamId = teams?.[0]?.id ?? null;
      if (!teamId) return jsonResult({ aviso: `Time "${time}" n\xE3o encontrado.`, objetivos: [] });
    }
    const wantOrg = !escopo || escopo === "todos" || escopo === "org";
    const wantTeam = !escopo || escopo === "todos" || escopo === "team";
    const orgPromise = wantOrg ? (() => {
      let q = supabase.from("okr_org_objectives").select(
        "id, title, description, status, owner_user_id, cycle_id, year, health_status, health_score, start_date, end_date"
      ).eq("bu_id", buId).is("deleted_at", null).is("cancelled_at", null).limit(limit);
      if (cycleId) q = q.eq("cycle_id", cycleId);
      if (status) q = q.eq("status", status);
      if (busca) q = q.ilike("title", `%${busca}%`);
      return q;
    })() : Promise.resolve({ data: [], error: null });
    const teamPromise = wantTeam ? (() => {
      let q = supabase.from("okr_team_objectives").select(
        "id, title, description, status, owner_user_id, team_id, cycle_id, is_shared, responsibility_model, health_status, health_score, avg_progress, kr_count, teams(name)"
      ).eq("bu_id", buId).is("deleted_at", null).is("cancelled_at", null).limit(limit);
      if (cycleId) q = q.eq("cycle_id", cycleId);
      if (teamId) q = q.eq("team_id", teamId);
      if (status) q = q.eq("status", status);
      if (busca) q = q.ilike("title", `%${busca}%`);
      return q;
    })() : Promise.resolve({ data: [], error: null });
    const [org, team] = await Promise.all([orgPromise, teamPromise]);
    assertNoError(org.error, "objetivos organizacionais");
    assertNoError(team.error, "objetivos de time");
    return jsonResult({
      unidade: scope.buName,
      ciclo: cycleName,
      objetivos_org: org.data ?? [],
      objetivos_time: (team.data ?? []).map((o) => ({
        ...o,
        time: (Array.isArray(o.teams) ? o.teams[0] : o.teams)?.name ?? null,
        teams: void 0
      }))
    });
  }
});

// src/lib/mcp/tools/list-key-results.ts
import { defineTool as defineTool8 } from "npm:@lovable.dev/mcp-js@2.0.4";
import { z as z7 } from "npm:zod@^3.25.76";
function progressOf(kr) {
  return calculateProgress(
    Number(kr.baseline) || 0,
    Number(kr.current_value) || 0,
    Number(kr.target) || 0,
    kr.direction ?? "up",
    { unit: kr.unit ?? null }
  );
}
var list_key_results_default = defineTool8({
  name: "list_key_results",
  title: "Listar key results (KRs)",
  description: "Lista KRs de time e organizacionais com baseline, resultado, meta, orienta\xE7\xE3o, progresso calculado, farol e data do \xFAltimo check-in. Permite filtrar por objetivo, time, respons\xE1vel, ciclo e KRs em risco.",
  inputSchema: {
    bu: buArg,
    escopo: z7.enum(["org", "team", "todos"]).optional(),
    objetivo_id: z7.string().optional().describe("Id do objetivo."),
    time: z7.string().optional(),
    ciclo: z7.string().optional().describe("Nome do ciclo. Omita para o ciclo ativo."),
    em_risco: z7.boolean().optional().describe("Se verdadeiro, retorna apenas KRs ativos com progresso abaixo de 70%."),
    busca: searchArg,
    limite: limitArg
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ bu, escopo, objetivo_id, time, ciclo, em_risco, busca, limite }, ctx) => {
    const scope = await resolveScope(ctx, bu);
    const { supabase, buId } = scope;
    const limit = clampLimit(limite, 100);
    const { data: cycles } = await supabase.from("cycles").select("id, name, status").eq("bu_id", buId).order("start_date", { ascending: false }).limit(60);
    const chosenCycle = ciclo ? (cycles ?? []).find((c) => c.name.toLowerCase().includes(ciclo.toLowerCase())) : (cycles ?? []).find((c) => c.status === "active");
    const cycleId = chosenCycle?.id ?? null;
    let teamId = null;
    if (time) {
      const { data: teams } = await supabase.from("teams").select("id, name").eq("bu_id", buId).is("deleted_at", null).ilike("name", `%${time}%`).limit(1);
      teamId = teams?.[0]?.id ?? null;
      if (!teamId) return jsonResult({ aviso: `Time "${time}" n\xE3o encontrado.`, key_results: [] });
    }
    const wantTeam = !escopo || escopo === "todos" || escopo === "team";
    const wantOrg = !escopo || escopo === "todos" || escopo === "org";
    const teamPromise = wantTeam ? (() => {
      let q = supabase.from("okr_team_key_results").select(
        "id, title, type, baseline, current_value, target, direction, unit, status, team_id, team_objective_id, owner_user_id, last_checkin_at, linked_org_kr_id, okr_team_objectives!inner(id, title, cycle_id, team_id), teams(name)"
      ).eq("bu_id", buId).is("deleted_at", null).is("cancelled_at", null).limit(limit);
      if (objetivo_id) q = q.eq("team_objective_id", objetivo_id);
      if (teamId) q = q.eq("team_id", teamId);
      if (cycleId && !objetivo_id) q = q.eq("okr_team_objectives.cycle_id", cycleId);
      if (busca) q = q.ilike("title", `%${busca}%`);
      return q;
    })() : Promise.resolve({ data: [], error: null });
    const orgPromise = wantOrg ? (() => {
      let q = supabase.from("okr_org_key_results").select(
        "id, title, baseline, current_value, target, direction, unit, status, org_objective_id, owner_user_id, okr_org_objectives!inner(id, title, cycle_id)"
      ).eq("bu_id", buId).is("deleted_at", null).is("cancelled_at", null).limit(limit);
      if (objetivo_id) q = q.eq("org_objective_id", objetivo_id);
      if (cycleId && !objetivo_id) q = q.eq("okr_org_objectives.cycle_id", cycleId);
      if (busca) q = q.ilike("title", `%${busca}%`);
      return q;
    })() : Promise.resolve({ data: [], error: null });
    const [teamRes, orgRes] = await Promise.all([teamPromise, orgPromise]);
    assertNoError(teamRes.error, "KRs de time");
    assertNoError(orgRes.error, "KRs organizacionais");
    const map = (row, escopoLabel) => {
      const parent = escopoLabel === "team" ? row.okr_team_objectives : row.okr_org_objectives;
      const objetivo = Array.isArray(parent) ? parent[0] : parent;
      return {
        id: row.id,
        escopo: escopoLabel,
        titulo: row.title,
        tipo: row.type ?? null,
        objetivo: objetivo?.title ?? null,
        objetivo_id: objetivo?.id ?? null,
        time: (Array.isArray(row.teams) ? row.teams[0] : row.teams)?.name ?? null,
        responsavel_id: row.owner_user_id,
        baseline: row.baseline,
        resultado: row.current_value,
        meta: row.target,
        orientacao: row.direction,
        unidade: row.unit,
        status: row.status,
        progresso_pct: Math.round(progressOf(row)),
        ultimo_checkin: row.last_checkin_at ?? null
      };
    };
    let krs = [
      ...(teamRes.data ?? []).map((r) => map(r, "team")),
      ...(orgRes.data ?? []).map((r) => map(r, "org"))
    ];
    if (em_risco) krs = krs.filter((k) => k.status === "active" && k.progresso_pct < 70);
    return jsonResult({
      unidade: scope.buName,
      ciclo: chosenCycle?.name ?? null,
      total: krs.length,
      key_results: krs
    });
  }
});

