// src/modules/kpis/utils/trendClassification.ts
function classifyOriented(rawDeltaPct, direction, bandPct) {
  const oriented = orientedDeltaPct(rawDeltaPct, direction === "down" ? "down" : "up");
  if (oriented == null) return null;
  const band = Math.abs(bandPct);
  if (Math.abs(oriented) <= band) return "stable";
  return oriented > 0 ? "growth" : "decline";
}
function classifyKpiTrendSeries(series, direction, options = {}) {
  const bandPct = options.bandPct ?? KPI_TREND_STABLE_BAND_PCT;
  const minPoints = options.minPoints ?? 3;
  const points = (series ?? []).filter((p) => p && typeof p.value === "number" && Number.isFinite(p.value)).slice().sort((a, b) => a.reference_date.localeCompare(b.reference_date));
  if (points.length < 2) return null;
  const n = points.length;
  const first = points[0];
  const last = points[n - 1];
  let rawDeltaPct;
  if (n >= minPoints) {
    const meanX = (n - 1) / 2;
    const meanY = points.reduce((acc, p) => acc + p.value, 0) / n;
    let num = 0;
    let den = 0;
    points.forEach((p, i) => {
      num += (i - meanX) * (p.value - meanY);
      den += (i - meanX) ** 2;
    });
    if (den === 0 || meanY === 0) return null;
    const slope = num / den;
    const totalChange = slope * (n - 1);
    rawDeltaPct = totalChange / Math.abs(meanY) * 100;
  } else {
    if (first.value === 0) return null;
    rawDeltaPct = (last.value - first.value) / Math.abs(first.value) * 100;
  }
  const trend = classifyOriented(rawDeltaPct, direction, bandPct);
  if (trend == null) return null;
  const oriented = orientedDeltaPct(rawDeltaPct, direction === "down" ? "down" : "up") ?? 0;
  return {
    trend,
    orientedPct: oriented,
    points: n,
    firstDate: first.reference_date,
    lastDate: last.reference_date
  };
}

// src/lib/mcp/tools/list-kpis.ts
var TREND_LABEL = {
  growth: "crescimento",
  stable: "estabilidade",
  decline: "queda"
};
var list_kpis_default = defineTool11({
  name: "list_kpis",
  title: "Listar KPIs e m\xE9tricas",
  description: "Lista os KPIs e m\xE9tricas da unidade com meta, orienta\xE7\xE3o, frequ\xEAncia, \xFAltimo valor consolidado, farol e tend\xEAncia (crescimento, estabilidade ou queda) calculada sobre a s\xE9rie consolidada.",
  inputSchema: {
    bu: buArg,
    categoria: z10.enum(["financeiro", "growth", "cs", "produto", "operacoes", "pessoas"]).optional(),
    tipo: z10.enum(["kpi", "metric"]).optional(),
    janela_meses: z10.number().int().optional().describe("Janela para a tend\xEAncia: 3, 6 ou 12 meses (padr\xE3o 6)."),
    busca: searchArg,
    limite: limitArg
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ bu, categoria, tipo, janela_meses, busca, limite }, ctx) => {
    const scope = await resolveScope(ctx, bu);
    const window = [3, 6, 12].includes(janela_meses ?? 6) ? janela_meses ?? 6 : 6;
    let query = scope.supabase.from("kpi_metrics").select(
      "id, name, description, category, indicator_type, unit, direction, target_value, status, lifecycle_status, scope, frequency, consolidation_frequency, update_frequency, owner_user_id, team_id, area_id"
    ).eq("bu_id", scope.buId).is("deleted_at", null).eq("status", "active").order("name").limit(clampLimit(limite, 100));
    if (categoria) query = query.eq("category", categoria);
    if (tipo) query = query.eq("indicator_type", tipo);
    if (busca) query = query.ilike("name", `%${busca}%`);
    const { data: metrics, error } = await query;
    assertNoError(error, "KPIs");
    const ids = (metrics ?? []).map((m) => m.id);
    const since = /* @__PURE__ */ new Date();
    since.setMonth(since.getMonth() - window - 1);
    const { data: values, error: valuesError } = ids.length ? await scope.supabase.from("kpi_values").select("kpi_id, value, reference_date, input_type, rag_status, period_label").in("kpi_id", ids).gte("reference_date", since.toISOString().slice(0, 10)).order("reference_date", { ascending: false }).limit(1200) : { data: [], error: null };
    assertNoError(valuesError, "valores de KPI");
    const byKpi = /* @__PURE__ */ new Map();
    for (const v of values ?? []) {
      const list = byKpi.get(v.kpi_id) ?? [];
      list.push(v);
      byKpi.set(v.kpi_id, list);
    }
    const kpis = (metrics ?? []).map((m) => {
      const all = byKpi.get(m.id) ?? [];
      const consolidated = all.filter((v) => v.input_type !== "partial");
      const latest = consolidated[0] ?? all[0] ?? null;
      const trend = classifyKpiTrendSeries(
        consolidated.map((v) => ({
          value: Number(v.value),
          reference_date: String(v.reference_date)
        })),
        m.direction ?? "up"
      );
      return {
        id: m.id,
        nome: m.name,
        descricao: m.description,
        categoria: m.category,
        tipo: m.indicator_type,
        unidade: m.unit,
        orientacao: m.direction,
        meta: m.target_value,
        frequencia: m.frequency ?? m.consolidation_frequency,
        escopo: m.scope,
        ciclo_de_vida: m.lifecycle_status,
        responsavel_id: m.owner_user_id,
        ultimo_valor: latest ? Number(latest.value) : null,
        ultimo_periodo: latest ? latest.period_label ?? latest.reference_date : null,
        farol: latest?.rag_status ?? null,
        tendencia: trend ? TREND_LABEL[trend.trend] : "sem dados suficientes",
        tendencia_pct: trend ? Math.round(trend.orientedPct * 10) / 10 : null,
        tendencia_pontos: trend?.points ?? consolidated.length
      };
    });
    return jsonResult({ unidade: scope.buName, janela_meses: window, total: kpis.length, kpis });
  }
});

// src/lib/mcp/tools/kpi-history.ts
import { defineTool as defineTool12 } from "npm:@lovable.dev/mcp-js@2.0.4";
import { z as z11 } from "npm:zod@^3.25.76";
var kpi_history_default = defineTool12({
  name: "kpi_history",
  title: "Hist\xF3rico de um KPI",
  description: "Retorna a s\xE9rie hist\xF3rica de um KPI da unidade (valores consolidados e parciais), com per\xEDodo, farol, origem e observa\xE7\xF5es.",
  inputSchema: {
    kpi: z11.string().describe("Nome ou id do KPI."),
    bu: buArg,
    desde: z11.string().optional().describe("Data inicial (AAAA-MM-DD)."),
    apenas_consolidados: z11.boolean().optional().describe("Padr\xE3o: falso (traz parciais tamb\xE9m)."),
    limite: limitArg
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ kpi, bu, desde, apenas_consolidados, limite }, ctx) => {
    const scope = await resolveScope(ctx, bu);
    const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(kpi);
    let metricQuery = scope.supabase.from("kpi_metrics").select("id, name, unit, direction, target_value, frequency, consolidation_frequency").eq("bu_id", scope.buId).is("deleted_at", null).limit(5);
    metricQuery = isUuid ? metricQuery.eq("id", kpi) : metricQuery.ilike("name", `%${kpi}%`);
    const { data: metrics, error: metricError } = await metricQuery;
    assertNoError(metricError, "KPIs");
    const metric = metrics?.[0];
    if (!metric) return jsonResult({ aviso: `KPI "${kpi}" n\xE3o encontrado na unidade ${scope.buName}.` });
    let query = scope.supabase.from("kpi_values").select("value, reference_date, period_start, period_end, period_label, input_type, rag_status, source, notes").eq("kpi_id", metric.id).order("reference_date", { ascending: false }).limit(clampLimit(limite, 60, 200));
    if (desde) query = query.gte("reference_date", desde);
    if (apenas_consolidados) query = query.neq("input_type", "partial");
    const { data, error } = await query;
    assertNoError(error, "valores de KPI");
    return jsonResult({
      unidade: scope.buName,
      kpi: {
        id: metric.id,
        nome: metric.name,
        unidade_medida: metric.unit,
        orientacao: metric.direction,
        meta: metric.target_value,
        frequencia: metric.frequency ?? metric.consolidation_frequency
      },
      alternativas: (metrics ?? []).slice(1).map((m) => m.name),
      valores: data ?? []
    });
  }
});

