// src/lib/mcp/tools/get-ticket.ts
import { defineTool as defineTool15 } from "npm:@lovable.dev/mcp-js@2.0.4";
import { z as z14 } from "npm:zod@^3.25.76";
var get_ticket_default = defineTool15({
  name: "get_ticket",
  title: "Detalhar um ticket",
  description: "Retorna os dados de um ticket e o hist\xF3rico de mensagens da conversa, al\xE9m dos participantes. Respeita as regras de visibilidade do Next.",
  inputSchema: {
    ticket_id: z14.string().describe("Id do ticket."),
    bu: buArg
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ ticket_id, bu }, ctx) => {
    const scope = await resolveScope(ctx, bu);
    const [ticketRes, messagesRes, participantsRes] = await Promise.all([
      scope.supabase.from("tickets").select(
        "id, title, type, status, expected_due_at, owner_user_id, created_by_user_id, visibility, external_company_id, created_at, updated_at"
      ).eq("id", ticket_id).is("deleted_at", null).maybeSingle(),
      scope.supabase.from("ticket_messages").select("id, author_type, author_user_id, author_contact_id, body_richtext, is_pinned, created_at, edited_at").eq("ticket_id", ticket_id).is("deleted_at", null).order("created_at", { ascending: true }).limit(200),
      scope.supabase.from("ticket_participants").select("participant_type, role, user_id, contact_id").eq("ticket_id", ticket_id).limit(100)
    ]);
    assertNoError(ticketRes.error, "o ticket");
    if (!ticketRes.data) {
      return jsonResult({ aviso: "Ticket n\xE3o encontrado ou sem permiss\xE3o de visualiza\xE7\xE3o." });
    }
    assertNoError(messagesRes.error, "as mensagens do ticket");
    return jsonResult({
      unidade: scope.buName,
      ticket: ticketRes.data,
      participantes: participantsRes.data ?? [],
      mensagens: messagesRes.data ?? []
    });
  }
});

