import { defineTool as defineTool19 } from "npm:@lovable.dev/mcp-js@2.0.4";
import { z as z18 } from "npm:zod@^3.25.76";
var list_partners_default = defineTool19({
  name: "list_partners",
  title: "Listar empresas parceiras",
  description: "Lista as empresas parceiras vinculadas \xE0 unidade, com raz\xE3o social, documento, situa\xE7\xE3o e os contatos externos de cada uma.",
  inputSchema: {
    bu: buArg,
    status: z18.enum(["active", "inactive"]).optional(),
    busca: searchArg,
    incluir_contatos: z18.boolean().optional().describe("Padr\xE3o: verdadeiro."),
    limite: limitArg
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ bu, status, busca, incluir_contatos, limite }, ctx) => {
    const scope = await resolveScope(ctx, bu);
    const { data: associations, error: assocError } = await scope.supabase.from("external_company_bu_associations").select("external_company_id").eq("bu_id", scope.buId).limit(500);
    assertNoError(assocError, "parceiros da unidade");
    const associated = (associations ?? []).map((a) => a.external_company_id);
    let query = scope.supabase.from("external_companies").select("id, name, legal_name, document, document_type, person_type, status, notes, created_at").is("deleted_at", null).order("name").limit(clampLimit(limite, 100));
    if (associated.length) query = query.in("id", associated);
    if (status) query = query.eq("status", status);
    if (busca) query = query.or([`name.ilike.%${busca}%`, `legal_name.ilike.%${busca}%`].join(","));
    const { data: companies, error } = await query;
    assertNoError(error, "empresas parceiras");
    const ids = (companies ?? []).map((c) => c.id);
    const wantContacts = incluir_contatos !== false && ids.length > 0;
    const { data: contacts } = wantContacts ? await scope.supabase.from("partner_contacts").select("id, external_company_id, name, email, phone, status, can_view_company_tickets, user_id").in("external_company_id", ids).is("deleted_at", null).limit(500) : { data: [] };
    return jsonResult({
      unidade: scope.buName,
      empresas: (companies ?? []).map((c) => ({
        id: c.id,
        nome: c.name,
        razao_social: c.legal_name,
        documento: c.document,
        tipo_documento: c.document_type,
        tipo_pessoa: c.person_type,
        status: c.status,
        observacoes: c.notes,
        contatos: wantContacts ? (contacts ?? []).filter((k) => k.external_company_id === c.id).map((k) => ({
          id: k.id,
          nome: k.name,
          email: k.email,
          telefone: k.phone,
          status: k.status,
          ve_tickets_da_empresa: k.can_view_company_tickets,
          tem_acesso: !!k.user_id
        })) : void 0
      }))
    });
  }
});

// src/lib/mcp/tools/list-analyses.ts
import { defineTool as defineTool20 } from "npm:@lovable.dev/mcp-js@2.0.4";
import { z as z19 } from "npm:zod@^3.25.76";
var list_analyses_default = defineTool20({
  name: "list_analyses",
  title: "Listar an\xE1lises e decis\xF5es",
  description: "Lista os relat\xF3rios de an\xE1lise da unidade (premissa, m\xF3dulos, per\xEDodo, resultado e a\xE7\xF5es sugeridas) e as decis\xF5es estrat\xE9gicas registradas neles.",
  inputSchema: {
    bu: buArg,
    status: z19.enum(["pending", "generating", "complete", "failed"]).optional(),
    incluir_resultado: z19.boolean().optional().describe("Se verdadeiro, inclui o texto completo do resultado (pode ser longo)."),
    busca: searchArg,
    limite: limitArg
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ bu, status, incluir_resultado, busca, limite }, ctx) => {
    const scope = await resolveScope(ctx, bu);
    let query = scope.supabase.from("analysis_reports").select(
      "id, title, premise, modules, scope, period, depth, status, suggested_actions, generated_at, created_at, result"
    ).eq("bu_id", scope.buId).is("deleted_at", null).order("created_at", { ascending: false }).limit(clampLimit(limite, 20, 100));
    if (status) query = query.eq("status", status);
    if (busca) query = query.ilike("title", `%${busca}%`);
    const { data: reports, error } = await query;
    assertNoError(error, "an\xE1lises");
    const ids = (reports ?? []).map((r) => r.id);
    const { data: decisions } = ids.length ? await scope.supabase.from("analysis_decisions").select("id, report_id, decisions, created_at").in("report_id", ids).is("deleted_at", null).limit(200) : { data: [] };
    return jsonResult({
      unidade: scope.buName,
      analises: (reports ?? []).map((r) => ({
        id: r.id,
        titulo: r.title,
        premissa: r.premise,
        modulos: r.modules,
        escopo: r.scope,
        periodo: r.period,
        profundidade: r.depth,
        status: r.status,
        acoes_sugeridas: r.suggested_actions,
        gerado_em: r.generated_at,
        resultado: incluir_resultado ? r.result : void 0,
        decisoes: (decisions ?? []).filter((d) => d.report_id === r.id).map((d) => d.decisions)
      }))
    });
  }
});

// src/lib/mcp/tools/search-next.ts
import { defineTool as defineTool21 } from "npm:@lovable.dev/mcp-js@2.0.4";
import { z as z20 } from "npm:zod@^3.25.76";
var search_next_default = defineTool21({
  name: "search_next",
  title: "Busca geral no Next",
  description: "Busca um termo em v\xE1rios m\xF3dulos ao mesmo tempo (pessoas, objetivos, KRs, KPIs, projetos, tickets, ativos e parceiros) e devolve os resultados agrupados por m\xF3dulo. Use quando n\xE3o souber onde o assunto est\xE1 registrado.",
  inputSchema: {
    termo: z20.string().min(2).describe("Texto a procurar."),
    bu: buArg
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ termo, bu }, ctx) => {
    const scope = await resolveScope(ctx, bu);
    const { supabase, buId } = scope;
    const like = `%${termo}%`;
    const [people, orgObj, teamObj, teamKr, kpis, projects, tickets, assets, partners] = await Promise.all([
      supabase.from("profiles").select("id, display_name, work_email, employment_status").eq("bu_id", buId).is("deleted_at", null).or([`display_name.ilike.${like}`, `work_email.ilike.${like}`, `email.ilike.${like}`].join(",")).limit(10),
      supabase.from("okr_org_objectives").select("id, title, status").eq("bu_id", buId).is("deleted_at", null).ilike("title", like).limit(10),
      supabase.from("okr_team_objectives").select("id, title, status, team_id").eq("bu_id", buId).is("deleted_at", null).ilike("title", like).limit(10),
      supabase.from("okr_team_key_results").select("id, title, status, current_value, target, unit").eq("bu_id", buId).is("deleted_at", null).ilike("title", like).limit(10),
      supabase.from("kpi_metrics").select("id, name, category, indicator_type").eq("bu_id", buId).is("deleted_at", null).ilike("name", like).limit(10),
      supabase.from("projects").select("id, name, status").eq("bu_id", buId).is("deleted_at", null).ilike("name", like).limit(10),
      supabase.from("tickets").select("id, title, status, type").eq("bu_id", buId).is("deleted_at", null).ilike("title", like).limit(10),
      supabase.from("asset_inventory").select("id, internal_code, name, status").eq("bu_id", buId).is("deleted_at", null).or([`name.ilike.${like}`, `internal_code.ilike.${like}`].join(",")).limit(10),
      supabase.from("external_companies").select("id, name, status").is("deleted_at", null).ilike("name", like).limit(10)
    ]);
    return jsonResult({
      unidade: scope.buName,
      termo,
      pessoas: people.data ?? [],
      objetivos_org: orgObj.data ?? [],
      objetivos_time: teamObj.data ?? [],
      key_results: teamKr.data ?? [],
      kpis: kpis.data ?? [],
      projetos: projects.data ?? [],
      tickets: tickets.data ?? [],
      ativos: assets.data ?? [],
      parceiros: partners.data ?? []
    });
  }
});

